const cfg=$('CONFIG — RESTORE FIXTURE').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>String(r.PROJECT_ID||'').trim()===cfg.project_id);
if(cfg.confirmation_token!==cfg.expected_confirmation_token) throw new Error('RESTORE_BLOCK: token mismatch');
if(rows.length===0) throw new Error('RESTORE_BLOCK: no snapshots for fixture');

const groups={};
for(const r of rows){
  const id=String(r.SNAPSHOT_ID||'').trim();
  if(!id) continue;
  if(!groups[id]) groups[id]=[];
  groups[id].push(r);
}
const candidates=Object.entries(groups).map(([id,rs])=>({
  id,
  rows:rs,
  ts:Math.max(...rs.map(r=>Date.parse(String(r.CREATED_AT||''))||0))
})).sort((a,b)=>b.ts-a.ts);
if(!candidates.length) throw new Error('RESTORE_BLOCK: no valid snapshot group');

const latest=candidates[0];
const mediaFields=["TRIAGEM", "QUALIDADE", "CONTEÚDO_VISUAL", "MELHOR_TRECHO", "USAR_EM", "ANALYSIS_STATUS", "ANALYSIS_VERSION", "ANALYSIS_SOURCE", "VISION_PROVIDER", "VISION_MODEL", "ANALYZED_AT", "ANALYSIS_ERROR", "EDITORIAL_SCORE", "PROXY_STATUS", "ANALYSIS_STAGE", "SHOT_TYPE", "TECHNICAL_NOTES", "TECHNICAL_SCORE", "COMPOSITION_SCORE", "TATTOO_VISIBILITY", "ANALYSIS_CONFIDENCE", "REDUNDANCY_HINT", "SCORE_SCALE_DETECTED", "SCORE_NORMALIZATION", "STRUCTURAL_ANALYSIS_VERSION", "GEOMETRY_MODE", "BODY_REGION", "BODY_SUBREGION", "VIEW_ANGLE", "BODY_POSE", "TATTOO_ORIENTATION", "TATTOO_STYLE_TAGS", "TATTOO_SUBJECT_PRIMARY", "TATTOO_SUBJECT_TAGS", "TATTOO_STAGE_STRUCTURAL", "TATTOO_COVERAGE", "COMPOSITION_SHAPE", "FOCAL_DESCRIPTION", "FOCUS_POINT_NORM", "TATTOO_BBOX_NORM", "CROP_GUIDANCE_JSON", "FORMAT_FIT_JSON", "BEST_FORMATS", "STRUCTURAL_CONFIDENCE", "STRUCTURAL_NOTES", "DATA_CAPTURA", "MIME_TYPE", "FILE_SIZE_BYTES", "CONTENT_HASH", "CAPTURED_AT_SOURCE", "TECHNICAL_METADATA_JSON", "PROCESS_STATUS", "RETRY_COUNT", "LAST_ATTEMPT_AT", "LAST_ERROR_CODE", "LAST_ERROR_MESSAGE", "LAST_FAILURE_STAGE", "LAST_FAILURE_NODE", "NEXT_RETRY_AT", "DEAD_LETTER_AT", "DEAD_LETTER_ID", "RELIABILITY_VERSION", "VIDEO_SAMPLING_MODE", "VIDEO_SAMPLING_VERSION", "SCENE_DETECTED_COUNT", "SELECTED_FRAME_COUNT", "SAMPLING_FALLBACK_USED", "SAMPLING_FALLBACK_REASON", "SAMPLING_DETAILS_JSON", "VIDEO_REANALYZED_AT", "CURATION_STATUS", "CURATION_VERSION", "CURATION_ROLE", "CURATION_RANK", "REDUNDANCY_GROUP", "REDUNDANCY_PREFERRED", "REDUNDANCY_REASON", "CAROUSEL_POSITION", "REEL_CANDIDATE", "CURATED_AT", "CURATION_PROVIDER", "CURATION_MODEL", "CURATION_CONFIDENCE", "CURATION_RUN_ID"];
const projectFields=["CURATION_STATUS", "CURATION_VERSION", "CURATION_HERO_ID", "CURATION_SELECTED_IDS", "CURATION_RESERVE_IDS", "CURATION_DISCARD_IDS", "CURATION_CAROUSEL_ORDER", "CURATION_REEL_IDS", "CURATION_NARRATIVE", "CURATION_CONFIDENCE", "CURATED_AT", "CURATION_PROVIDER", "CURATION_MODEL", "CURATION_RUN_ID", "CONTENT_PLAN_STATUS", "CONTENT_PLAN_VERSION", "CONTENT_PLAN_RUN_ID", "CONTENT_PLAN_CURATED_FROM", "CONTENT_PLAN_AT", "CONTENT_PLAN_COUNT", "CONTENT_PLAN_PROVIDER", "CONTENT_PLAN_MODEL"];
const contentFields=["PLAN_STATUS", "STATUS_EDIÇÃO", "STATUS_APROVAÇÃO", "EDITORIAL_APPROVAL_STATUS", "EDITORIAL_COMMITTED_STATUS", "EDITORIAL_APPROVAL_NOTES", "EDITORIAL_DECIDED_AT", "EDITORIAL_APPROVAL_VERSION", "EDITORIAL_APPROVAL_SOURCE", "FINAL_APPROVAL_STATUS", "FINAL_COMMITTED_STATUS", "FINAL_APPROVAL_NOTES", "FINAL_APPROVAL_DECIDED_AT", "FINAL_APPROVAL_VERSION", "FINAL_APPROVAL_SOURCE", "ROUTING_STATUS", "ROUTING_VERSION", "ROUTING_DECISION", "ROUTING_TARGET", "ROUTED_AT", "ROUTING_SOURCE", "ROUTED_FROM_EDITORIAL_AT", "PRODUCTION_STATUS", "REVISION_STATUS", "EDITORIAL_STATUS", "RENDER_STATUS", "RENDER_ID", "RENDER_RECIPE_ID", "QA_STATUS", "QA_NOTES", "PIPELINE_STATE", "STATE_UPDATED_AT", "STATE_VERSION", "FINAL_ARTIFACT_HASH", "OBSERVAÇÕES"];

const media=[], projects=[], content=[];
for(const s of latest.rows){
  let payload;
  try{payload=JSON.parse(String(s.PAYLOAD_JSON||'{}'));}catch(e){throw new Error(`RESTORE_BLOCK: invalid payload for ${s.ENTITY_ID}`);}
  if(s.ENTITY_TYPE==='MEDIA'){
    const u={ID_MIDIA:payload.ID_MIDIA};
    for(const f of mediaFields) u[f]=payload[f] ?? '';
    media.push(u);
  } else if(s.ENTITY_TYPE==='PROJECT'){
    const u={ID_PROJETO:payload.ID_PROJETO};
    for(const f of projectFields) u[f]=payload[f] ?? '';
    projects.push(u);
  } else if(s.ENTITY_TYPE==='CONTENT'){
    const u={ID_CONTEÚDO:payload.ID_CONTEÚDO};
    for(const f of contentFields) u[f]=payload[f] ?? '';
    content.push(u);
  }
}
if(media.length<1 || projects.length!==1) throw new Error('RESTORE_BLOCK: incomplete latest snapshot');

return [{json:{
  status:'RESTORE_PREPARED',
  project_id:cfg.project_id,
  snapshot_id:latest.id,
  snapshot_created_at:new Date(latest.ts).toISOString(),
  media_updates:media,
  project_updates:projects,
  content_updates:content
}}];

const x=$input.first().json;
if(x.project_id!=='TATTOO_0002') throw new Error('RESTORE_BLOCK: wrong project');
if(!x.snapshot_id) throw new Error('RESTORE_BLOCK: missing snapshot id');
return [{json:{...x,restore_guard:true}}];

const x=$('GUARD — RESTORE').first().json;
return [{json:{
  status:'SM3_TEST_FIXTURE_RESTORE_PASS',
  project_id:x.project_id,
  snapshot_id:x.snapshot_id,
  media_restored:x.media_updates.length,
  projects_restored:x.project_updates.length,
  content_restored:x.content_updates.length,
  completed_at:new Date().toISOString()
}}];
